ALTER TABLE guild_events ADD COLUMN SpendReceiptId TEXT NULL CHECK(SpendReceiptId IS NULL OR (typeof(SpendReceiptId)='text' AND SpendReceiptId=upper(SpendReceiptId) AND length(SpendReceiptId)=36 AND substr(SpendReceiptId,9,1)='-' AND substr(SpendReceiptId,14,1)='-' AND substr(SpendReceiptId,19,1)='-' AND substr(SpendReceiptId,24,1)='-' AND length(replace(SpendReceiptId,'-',''))=32 AND replace(SpendReceiptId,'-','') NOT GLOB '*[^0-9A-F]*' AND SpendReceiptId<>'00000000-0000-0000-0000-000000000000'));
